  str_maze_word_desc_40022 = "การโจมตีปกติของมอนสเตอร์มีโอกาสติดตาบอด 100% (ตาบอด: ดาเมจออโรเรียนทั้งหมดที่เข้าหาศัตรูจะพลาดเป้า นาน 1 รอบ)",
