  str_maze_word_desc_40051 = "ทุกครั้งที่ออโรเรียนใช้สกิลใช้งาน ATK ของมอนสเตอร์ทั้งหมดในสนามรบจะเพิ่มขึ้น 3% และจะฟื้นฟู 3% ของ HP สูงสุด เมื่อมอนสเตอร์ถูกโจมตีด้วยคอมโบต่อเนื่อง DEF ของมันจะลดลง 5%",
