  str_maze_word_desc_40054 = "เมื่อในกระดานมีมอนสเตอร์พ่ายแพ้ มอนสเตอร์ตัวอื่น ๆ จะคลุ้มคลั่ง พร้อมเพิ่ม ATK และความเร็วเคลื่อนที่",
  str_maze_word_desc_40055 = "เมื่อในกระดานมีมอนสเตอร์พ่ายแพ้ มอนสเตอร์ตัวอื่น ๆ จะคลุ้มคลั่ง พร้อมเพิ่ม ATK และความเร็วเคลื่อนที่",
  str_maze_word_desc_40056 = "ออโรเรียนฟื้นฟู HP เมื่อเดินผ่านช่องหลากสีแต่ละช่อง ทุก 10 Vis ที่ออโรเรียนในตำนานใช้ไป จะสร้างช่องหลากสีขึ้น 1 ช่อ",
  str_maze_word_desc_40057 = "ระหว่างออโรราไทม์ ผู้เล่นจะเรียกสายฟ้า 1 ครั้ง เมื่อสร้างความเสียหายจากการโจมตีปกติทุก 4 ครั้ง",
  str_maze_word_desc_40058 = "ระหว่างออโรราไทม์ จุดอ่อนของมอนสเตอร์จะถูกเผยออกมา จะลด DEF ของพวกมันลงอย่างมาก",
