  str_maze_word_desc_400631 = "การเปลี่ยนลำดับในทีมจะเปิดใช้สกิลกับดักสนามรบ เมื่อจบรอบจะเพิ่มจำนวนกัปตันที่เปลี่ยนแปลงได้",
