  str_maze_word_desc_40089 = "อิคลิพไซท์จะสะสมรอยฟกช้ำเมื่อได้รับดาเมจ ทุกครั้งที่อิคลิพไซท์ทำดาเมจกับออโรเรียน ATK ของมันจะเพิ่มขึ้น และมันจะฟื้นฟู HP บางส่วนตามจำนวนรอยฟกช้ำที่มี",
