  str_maze_word_desc_40101 = "เมื่อกลางคืนและกลางวันสลับช่วงเวลากัน อิคลิพไซท์ทั้งหมดจะโคลนตัวเอง HP ของตัวโคลนจะเท่ากับ 20% ของ HP รวมของตัวหลัก",
