  str_maze_word_desc_40108 = "คลอเดีย: เมื่อเริ่มรอบ คลอเดียจะเรียกแพลตฟอร์มสูงสุด 5 แพลตฟอร์มตรงขอบสนาม",
  str_maze_word_desc_40109 = "คลอเดีย: เมื่อเริ่มรอบ คลอเดียจะเรียกแพลตฟอร์มสูงสุด 10 แพลตฟอร์มตรงขอบสนาม",
  str_maze_word_desc_40110 = "คลอเดีย: เมื่อเริ่มรอบ คลอเดียจะเรียกแพลตฟอร์มสูงสุด 2 แพลตฟอร์มตรงขอบสนาม",
  str_maze_word_desc_40114 = "เมื่อเริ่มรอบของมอนสเตอร์ จะสุ่มเรียกช่องเสริมพลัง 3 ช่อง และช่องอ่อนแอ 4 ช่อง",
  str_maze_word_desc_401141 = "เมื่อเริ่มต้นแต่ละรอบ จะสุ่มเรียกช่องเสริมพลัง 3 ช่อง และช่องอ่อนแอ 4 ช่อง",
  str_maze_word_desc_40120 = "เมื่อเดินผ่านช่องที่เสียหาย ออโรเรียนและอิคลิพไซท์จะเพิ่ม DEF 20% นาน 1 รอบ",
  str_maze_word_desc_40121 = "ในตอนกลางคืน เมื่ออิคลิพไซท์โจมตี จะเพิ่มเวลาคูลดาวน์ 1 รอบ ให้กับสกิลใช้งานของออโรเรียนแบบสุ่ม",
  str_maze_word_desc_40122 = "เมื่อตาย อิคลิพไซท์จะลดเวลาคูลดาวน์ 1 รอบ ให้กับสกิลใช้งานของออโรเรียนแบบสุ่ม 2 ตัว",
