  str_maze_word_desc_40130 = "ยิ่งอิคลิพไซท์มีขนาดใหญ่ ก็ยิ่งได้รับดาเมจจากการโจมตีเป้าหมายเดียวมากขึ้น",
  str_maze_word_desc_40131 = "อิคลิพไซท์ได้รับบัฟต้านกายภาพและได้รับดาเมจโจมตีปกติน้อยลง",
