  str_maze_word_desc_40136 = "หลังจากสังหารศัตรูแล้ว ทิ้งระเบิดตัวตลกไว้ที่ตำแหน่ง ซึ่งจะระเบิดใน 1 รอบและสร้างความเสียหายแก่เป้าหมายภายใน 1 กลุ่มที่อยู่โดยรอบ",
  str_maze_word_desc_40137 = "ทุกๆ 3 รอบ จะเรียกรูน 3 ตัวที่กลายเป็น Gloom Ghouls หลังจาก 2 รอบไปยังตำแหน่งแบบสุ่มบนสนาม",
  str_maze_word_desc_40138 = "เมื่อใดก็ตามที่ Eclipsite บนสนามตาย เพิ่ม ATK ของ Eclipsites ที่เหลืออีก 5% วางซ้อนกันได้",
  str_maze_word_desc_40139 = "ในช่วงเปลี่ยนวันและคืน DEF ของทั้งฝ่ายเดียวกันและศัตรูจะลดลง 10%",
  str_maze_word_desc_40140 = "Enferno มีภูมิคุ้มกันต่อความเสียหายทั้งหมดและไม่สามารถตกเป็นเป้าหมายของการโจมตีได้",
  str_maze_word_desc_3101 = "DMG ของทั้งฝ่ายเราและศัตรูเพิ่มขึ้นในแต่ละรอบ ตามการลดลงของค่าสุขภาพจิต",
  str_maze_word_desc_3102 = "อัตราคริติคอลของออโรเรียนเพิ่มขึ้นในแต่ละรอบ ตามการลดลงของค่าสุขภาพจิต",
  str_maze_word_desc_3103 = "เมื่อเริ่มรอบ หากเข้าสู่สถานะบ้าคลั่ง ช่องต่าง ๆ จะเปลี่ยนสีเป็นธาตุเดียวกับกัปตัน พร้อมกับเกิดช่องแตกจำนวนมาก",
  str_maze_word_desc_3104 = "เมื่อค่าสุขภาพจิตต่ำกว่า 50 อิคลิพไซท์บนสนามจะเพิ่มความแข็งแกร่ง แต่ HP ของพวกมันจะลดลง 10% ของ Max HP ในทุก ๆ รอบ",
  str_maze_word_desc_5000 = "ระเบิดอารมณ์แผ่ซ่านในอากาศ ลดดาเมจของผู้เล่น",
  str_maze_word_desc_5001 = "อิคลิพไซท์ที่น่ากลัวโจมตีเป็นระลอก พลังความมืดที่ถาโถมจะกัดกร่อนพลังกายของผู้เล่น",
  str_maze_word_desc_5002 = "อิคลิพไซท์ที่น่ากลัวโจมตีเป็นระลอก พลังความมืดที่ถาโถมจะกัดกร่อนพลังกายของผู้เล่น แสงอันเจิดจ้าสามารถปกป้องผู้เล่นได้",
  str_maze_word_desc_5003 = "เพลิงโทสะสวาปามทุกสิ่งที่ขวางหน้า กลืนกินทุกซอกทุกมุมของห้องปฏิบัติการ",
  str_maze_word_desc_5004 = "โอกาสในการชนะซ่อนอยู่ในวัตถุที่คุณสามารถทำลายได้",
  str_maze_word_desc_5005 = "กับดักมีความอันตรายมาก จงหลีกเลี่ยงมันให้ได้!",
  str_maze_word_desc_5010 = "สร้างช่องเสริมพลังและช่องอ่อนแอจำนวนมากในทุก ๆ รอบ",
  str_maze_word_desc_5020 = "ในตอนกลางคืน ช่องเสริมพลังทั้งหมดจะกลายเป็นช่องอ่อนแอ",
  str_maze_word_desc_5021 = "เมื่อออโรเรียนเดินบนช่องอ่อนแอ จะสะสมเอฟเฟกต์อ่อนแอ แต่ละสแต็กลด ATK ของพวกเขา 3% ช่องเสริมพลังสามารถลดสแต็กอ่อนแอได้",
  str_maze_word_desc_5030 = "เมื่อออโรเรียนเดินบนช่องเสริมพลัง จะทำดาเมจกับศัตรูที่มี HP สูงสุด เท่ากับเปอร์เซ็นต์ของ Max HP",
  str_maze_word_desc_5040 = "เมื่อถูกออโรเรียนเดินเหยียบ ช่องเสริมพลังจะเปลี่ยนเป็นช่องอ่อนแอ และช่องอ่อนแอจะเปลี่ยนเป็นช่องเสริมพลัง",
  str_maze_word_desc_5032003 = "เมื่อไรก็ตามที่อิคลิพไซท์ถูกกำจัด ราชินีผู้มากเล่ห์ - CAROLINE จะสูญเสีย 10% ของ Max HP ของเธอ",
  str_maze_word_desc_5032011 = "เมื่อไรก็ตามที่อิคลิพไซท์ถูกกำจัด อิคลิพไซท์ตัวอื่นจะได้รับการรักษาจน HP เต็ม และได้รับ ATK เพิ่มขึ้น 15%",
