  str_maze_word_desc_40141 = "เส้นทางที่มอนสเตอร์เดินต่อไปจะกลายเป็นพื้นที่ตื่นตระหนกเป็นเวลา 2 รอบ",
  str_maze_word_desc_40142 = "สถานที่ที่ชาวออโรเรียนเริ่มรอบจะกลายเป็นพื้นที่ตื่นตระหนก 2 รอบ",
  str_maze_word_desc_40143 = "Aurorians จะได้รับ Bleeding 1 กองต่อทุกๆ 1 แผ่นที่เดินทางในพื้นที่ Alarming Area สูงสุด 5 กอง",
  str_maze_word_desc_40144 = "ชาวออโรเรียนได้รับความเสียหายเท่ากับ 1.5% ของ HP สูงสุด สำหรับทุก ๆ 1 แผ่นที่เดินทางในพื้นที่ตื่นตระหนก\nสำหรับทุก ๆ 4 แผ่นที่เดินทางในพื้นที่ช่วยเหลือ สายฟ้าจะถูกเรียกลงมาเพื่อสร้างความเสียหายให้กับศัตรูทั้งหมด",
  str_maze_word_desc_40145 = "Aurorians รับความเสียหายเท่ากับ 1.5% ของ HP สูงสุดสำหรับทุก ๆ 1 แผ่นที่เดินทางในพื้นที่ที่น่าตกใจและจะฮีลเมื่อเคลื่อนที่ในพื้นที่ช่วยเหลือ",
  str_maze_word_desc_40146 = "พื้นที่ที่น่าตกใจเติบโตขึ้นเมื่อเวลาผ่านไป",
  str_maze_word_desc_40147 = "พื้นที่ช่วยเหลือจะเล็กลงเมื่อเวลาผ่านไป",
  str_maze_word_desc_40148 = "ชาวออโรเรียนได้รับความเสียหายเท่ากับ 1.5% ของ HP สูงสุด สำหรับทุก ๆ 1 แผ่นที่เดินทางในพื้นที่ตื่นตระหนก",
  str_maze_word_desc_40149 = "การโจมตีของ Aurorians ทำให้เกิด Bleeding ในพื้นที่ Alarming แต่จะได้รับความเสียหาย 1.5% ของ HP สูงสุด ทุกๆ 1 แผ่นที่เดินทางในพื้นที่ Alarming",
  str_maze_word_desc_40150 = "Aurorians สร้างความเสียหายเพิ่มขึ้น แต่รับความเสียหายเท่ากับ 1.5% ของ HP สูงสุด สำหรับทุก ๆ 1 แผ่นที่เดินทางในพื้นที่ที่น่าตกใจ",
  str_maze_word_desc_40151 = "ชาวออโรเรียนถูกทำให้ตาบอดในพื้นที่ตื่นตระหนก และมีโอกาส 50% ที่การโจมตีของพวกเขาจะถูกหลบเลี่ยง",
  str_maze_word_desc_40152 = "ชาวออโรเรียนมีเลือดออกเมื่อเดินทางในพื้นที่เตือนภัยและจะรักษาให้หายเมื่อเคลื่อนที่ในพื้นที่ช่วยเหลือ",
  str_maze_word_desc_40153 = "ศัตรูจะสร้างพื้นที่ตื่นตระหนกทันทีที่พวกมันตาย",
  str_maze_word_desc_40154 = "พื้นที่ช่วยเหลือถูกสร้างขึ้นในจุดที่ศัตรูถูกฆ่า",
  str_maze_word_desc_40155 = "ชาวออโรเรียนได้รับความเสียหายเท่ากับ 15% ของ HP สูงสุด และศัตรูจะได้รับการปรับปรุงภายในพื้นที่ตื่นตระหนก",
  str_maze_word_desc_40156 = "ในช่วงเปลี่ยนวันและคืน พื้นที่เตือนภัยและพื้นที่ช่วยเหลือจะสลับสถานที่",
  str_maze_word_desc_40157 = "สำหรับทุก 4 แผ่นที่เดินทางโดย Aurorians ในพื้นที่ช่วยเหลือ จะสร้าง 1 แผ่นสีใน 1 กระจุกโดยรอบ",
  str_maze_word_desc_40158 = "พื้นที่ตื่นตระหนกใหญ่ขึ้นทุกรอบในเวลากลางคืน",
  str_maze_word_desc_40159 = "Aurorians ได้รับความเสียหายเท่ากับ 15% ของ HP สูงสุดเมื่ออยู่ในพื้นที่เตือนภัย สำหรับทุก 4 แผ่นที่เดินทางในพื้นที่ช่วยเหลือ จะสร้าง 1 แถบสีใน 1 คลัสเตอร์โดยรอบ",
  str_maze_word_desc_40160 = "ชาวออโรเรียนมีเลือดออกเมื่อเดินทางในพื้นที่เตือนภัยและจะรักษาให้หายเมื่อเคลื่อนที่ในพื้นที่ช่วยเหลือ",
