  str_maze_word_desc_40163 = "ในช่วงเปลี่ยนวันและคืน พื้นที่เตือนภัยและพื้นที่ช่วยเหลือจะเปลี่ยนตำแหน่ง และรอยช้ำสะสมของศัตรูจะถูกแปลงเป็น HP",
