  str_maze_word_desc_4101052 = "เมื่อ Caracalune ใช้ทักษะอย่างต่อเนื่องในตำแหน่งเดิม ATK ของมันจะเพิ่มขึ้นอย่างต่อเนื่อง ATK จะถูกรีเซ็ตและ DEF จะลดลงชั่วคราวหลังจาก Caracalune เคลื่อนที่",
