  str_maze_word_40213 = "คำสั่งกับดัก",
  str_maze_word_desc_40213 = "เมื่อ Aurorian เทเลพอร์ตไปที่ Pedal I พวกเขาจะดึงสัตว์ประหลาดมาหาตัวเอง เมื่อ Aurorians เทเลพอร์ตไปที่ Pedal II มอนสเตอร์จะถูกกระแทกกลับ",
