  str_maze_word_desc_40214 = "ความช่วยเหลือด้านทักษะของ Brock",
  str_maze_word_desc_40215 = "ความช่วยเหลือด้านทักษะของ Regina",
  str_maze_word_desc_40216 = "เมื่อสัตว์ประหลาดกระเบื้องแผ่นเดียวเคลื่อนไหว พวกมันจะสร้างกับดักเพลิงที่จะเผา Aurorian ที่เหยียบพวกมัน",
  str_maze_word_40217 = "เจตจำนงแห่งแสง",
