  str_maze_word_40218 = "ฟอร์เซคิน: โรยรา",
  str_maze_word_desc_40218 = "ฆ่า Eclipsites ให้เร็วที่สุด! หากมี Eclipsites มากเกินไปรอบๆ Forsakin สิ่งเลวร้ายอาจเกิดขึ้น",
