  str_maze_word_40219 = "รูปปั้นผู้พิทักษ์",
  str_maze_word_desc_40219 = "กำจัด Eclipsites ให้เร็วที่สุดเท่าที่จะทำได้เพื่อปกป้องรูปปั้น!",
  str_maze_word_40220 = "ปกป้องทูร์ด็อก",
  str_maze_word_desc_40220 = "Tourdog ติดตาม Aurorians ขณะที่พวกเขาเคลื่อนไหวและเรียกสายฟ้าเพื่อโจมตีศัตรูในแต่ละรอบ ถ้า Tourdog ตาย คุณจะแพ้การต่อสู้ ดังนั้นรักษา Tourdog ให้ปลอดภัย!",
  str_maze_word_desc_40221 = "Tourdog เคลื่อนตัวออกห่างจาก Aurorians และเมื่อเขาหยุด มันจะเรียก Meteorite Scroll ภายในกลุ่ม 1 รอบ หลังจาก Tourdog ตาย DEF ของศัตรูจะเพิ่มขึ้น 20% รักษา Tourdog ให้ปลอดภัย!",
  str_maze_word_desc_40222 = "Tourdog สร้างกระเบื้องสี 2 แผ่นรอบตัวเขาในแต่ละรอบ หลังจาก Tourdog ตาย รีเซ็ตไทล์ทั้งหมด และ ATK และ DEF ของศัตรูเพิ่มขึ้น 10%",
  str_maze_word_desc_40223 = "Tourdog ติดตาม Aurorians ขณะที่พวกเขาเคลื่อนไหว หลังจาก Tourdog เสียชีวิต ศัตรูตัวฉกาจคนใหม่ก็ปรากฏตัวขึ้น รักษา Tourdog ให้ปลอดภัย!",
  str_maze_word_desc_40224 = "Tourdog ถอยห่างจาก Aurorians หลังจาก Tourdog ตาย ATK และ DEF ของศัตรูเพิ่มขึ้น 20% รักษา Tourdog ให้ปลอดภัย!",
  str_maze_word_desc_40225 = "Tourdog จะย้ายออกจาก Aurorians ถ้า Tourdog ตาย คุณจะแพ้การต่อสู้ ดังนั้นรักษา Tourdog ให้ปลอดภัย!",
  str_maze_word_desc_40226 = "ถ้า Tourdog ตาย คุณจะแพ้การต่อสู้ ดังนั้นรักษา Tourdog ให้ปลอดภัย!",
  str_maze_word_desc_40227 = "ถ้า Tourdog ตาย คุณจะแพ้การต่อสู้ ดังนั้นรักษา Tourdog ให้ปลอดภัย!",
