  str_maze_word_40229 = "หนึ่งวิญญาณ",
  str_maze_word_desc_40229 = "เมื่อใดก็ตามที่ Dreadblades Elite ถูกโจมตีหรือฟื้นฟู HP Elite Dreadblades อื่นจะได้รับความเสียหายเท่ากันหรือกู้คืน HP ในปริมาณที่เท่ากัน",
