  str_maze_word_desc_402211 = "Tourdog ออกห่างจาก Aurorians และเรียก Meteorite Scroll หลังจาก Tourdog ตาย DEF ของศัตรูจะเพิ่มขึ้น 20%",
  str_maze_word_desc_402221 = "Tourdog สร้างกระเบื้องสีรอบตัวเขาในแต่ละรอบ หลังจาก Tourdog ตาย รีเซ็ตไทล์ทั้งหมด และ ATK และ DEF ของศัตรูจะเพิ่มขึ้น",
  str_maze_word_40231 = "เทรเชอร์ เรดเดอร์ส",
