  str_maze_word_desc_11160511 = "ในช่วงเริ่มต้นของรอบมอนสเตอร์ หาก Eclipsite Dreadblades ชั้นยอดมี HP เหลือน้อยกว่า 30% จะใช้ HP 30% ของ Eclipsites ที่เชื่อมโยงเพื่อรักษาตัวเอง",
  str_maze_word_desc_11160611 = "สำหรับไทล์ทุกอันที่เสียหายบนสนาม Eclipsites จะได้รับพลังโจมตีและป้องกันเพิ่มขึ้น 1%",
