  str_maze_word_desc_10161111 = "ในตอนต้นของรอบ สุ่มเรียกก้อนกรวด 2 ก้อนมาที่สนาม",
  str_maze_word_desc_10161611 = "Eclipsites ได้รับเครื่องหมาย 3 ชั้นสำหรับทุก ๆ รอบที่พวกเขาอยู่รอดและสูญเสียเครื่องหมาย 1 ชั้นเมื่อได้รับความเสียหาย แต่ละชั้นของเครื่องหมายจะเพิ่ม ATK ของ Eclipsites 5%",
  str_maze_word_desc_10161711 = "Lantern Spirit ได้รับเกราะป้องกัน 1 ชั้นทันทีที่เชื่อมโยงกับผู้เล่นและล็อคไทล์รอบ ๆ 2 อันแบบสุ่ม",
  str_maze_word_desc_10161712 = "Fire Trap สร้าง Flaming Trap ภายในระยะการโจมตี ยิ่ง HP รวมของศัตรูสูงเท่าไร พวกมันก็จะได้รับความเสียหายมากขึ้นเท่านั้น",
  str_maze_word_desc_11160111 = "Spikepest ที่มีความสามารถพิเศษติดอยู่ ดูเหมือนว่าจะมีปัญหาในการแยกแยะระหว่างมิตรกับศัตรู",
  str_maze_word_desc_11160211 = "ชาโดว์ วอล์กเกอร์เข้าสู่ห้วงนิทราในยามราตรี หากมันถูกปลุกโดยการโจมตีจากพวกออโรเรียน ATK ของมันจะได้รับการเพิ่มอย่างมากภายใน 2 รอบ",
  str_maze_word_desc_11160512 = "ในตอนท้ายของรอบ Dreadblades จะเชื่อมโยงกับ Eclipsite ที่มี HP ต่ำที่สุดในสนาม ทำให้ส่วนหลังได้รับความเสียหายส่วนหนึ่ง",
