  str_maze_word_desc_10161211 = "Eclipsites สร้างกระเบื้องแตกไม่ว่าจะผ่านที่ใด",
  str_maze_word_5309001 = "Wailer Defence",
  str_maze_word_desc_5309001 = "หลังจากได้รับความเสียหายเป็นกระเบื้อง Lurking Wailer จะล่าถอยและออกจากโหมดป้องกัน ต้านทานความเสียหายทั้งหมดและเริ่มโจมตี Aurorian อย่างต่อเนื่อง ระวัง!",
