  str_maze_word_desc_4005001 = "ขยายขอบเขตของสกิลการส่งเสริมของ Shadow Walker ออกไปทั้งสนาม",
  str_maze_word_4005002 = "ระเบิดแสง",
  str_maze_word_desc_4005002 = "หลังจากเทเลพอร์ต Aurorian จะสตัน Eclipsites ทั้งหมดภายใน 1 กลุ่มที่อยู่รอบๆ และลด DEF ของพวกมัน",
  str_maze_word_40050021 = "โลกกระจก",
