  str_maze_word_desc_5308001 = "เมื่อเริ่มรอบของศัตรู ภูมิประเทศของห้องจะเปลี่ยนไป ระวังกับดักใหม่ที่ปรากฏขึ้น!",
  str_maze_word_desc_5308002 = "เมื่อเริ่มรอบของศัตรู ภูมิประเทศของห้องจะเปลี่ยนไป ระวังกับดักใหม่ที่ปรากฏขึ้น!",
  str_maze_word_desc_5308003 = "Eclipsites ที่มีเอฟเฟกต์การเสริมประสิทธิภาพจะถ่ายโอนเอฟเฟกต์การเสริมประสิทธิภาพไปยังศัตรูทั้งหมดภายใน 2 กลุ่มรอบ ๆ ทุกรอบ วางซ้อนกันได้",
  str_maze_word_desc_5308004 = "Eclipsites ที่มีเอฟเฟกต์การเสริมประสิทธิภาพจะถ่ายโอนเอฟเฟกต์การเสริมประสิทธิภาพไปยังศัตรูทั้งหมดภายใน 2 กลุ่มรอบ ๆ ทุกรอบ Aurorians ที่แปดเปื้อนจะสูญเสีย DEF วางซ้อนกันได้",
  str_maze_word_desc_5308005 = "ทุกๆ รอบ Unimet จะขว้าง Lightning Crystals 2 ชิ้นและแปลงกระเบื้องเป็นกระเบื้องสีเหลือง\nการตายของ Unimet ทำให้ Lightning Crystals ทั้งหมดทำงาน และกระเบื้องที่อยู่ข้างใต้จะกลายเป็นกระเบื้องแตกเป็นเวลา 5 รอบ",
  str_maze_word_desc_5308006 = "Unimet ขว้าง Lightning Crystals ในทุก ๆ รอบเพื่อช่วยผู้เล่นทุกครั้งที่ Aurorians เดินบนกระเบื้องสีเหลือง หลังจากที่ Unimet ตาย แผ่นเส้นทางการเคลื่อนที่ของศัตรูจะกลายเป็นแผ่นกระเบื้องที่เสียหาย",
  str_maze_word_desc_5308007 = "ความเสียหายที่ Vice ได้รับจะถูกโอนไปยังผู้เล่นพร้อมกัน ช่วยให้เธอหลบหนีและต่อสู้ด้วยกัน! ATK และ DEF ของศัตรูจะเพิ่มขึ้นอย่างมากหลังจาก Vice พ่ายแพ้",
  str_maze_word_desc_5308008 = "ความเสียหายที่ Vice ได้รับจะถูกโอนไปยังผู้เล่นพร้อมกัน ช่วยให้เธอหลบหนีและต่อสู้ด้วยกัน! คุณจะแพ้ทันทีหาก Vice พ่ายแพ้",
  str_maze_word_desc_5308009 = "ในระหว่างวัน ศัตรูจะฟื้น HP และได้รับการปรับปรุงอย่างถาวรเมื่อพวกเขาเข้าสู่พื้นที่อันตราย พวกมันยังสะท้อนความเสียหายในขณะที่พวกมันอยู่ในพื้นที่อันตรายอีกด้วย",
  str_maze_word_desc_53080091 = "ในระหว่างวัน ศัตรูจะถูกเทเลพอร์ตไปยังพื้นที่อันตราย ฟื้นฟู HP และได้รับการปรับปรุงอย่างถาวร พวกมันยังสะท้อนความเสียหายในขณะที่พวกมันอยู่ในพื้นที่อันตรายอีกด้วย",
  str_maze_word_desc_5308010 = "ในระหว่างวัน ศัตรูจะฟื้น HP และได้รับการปรับปรุงอย่างถาวรเมื่อพวกเขาเข้าสู่พื้นที่อันตราย พื้นที่อันตรายจะขยายตัวขึ้นเรื่อยๆ",
  str_maze_word_desc_53080101 = "ในระหว่างวัน ศัตรูจะถูกเทเลพอร์ตไปยังพื้นที่อันตราย ฟื้นฟู HP และได้รับการปรับปรุงอย่างถาวร พื้นที่อันตรายจะขยายตัวขึ้นเรื่อยๆ",
  str_maze_word_desc_5309003 = "Aurorians สูญเสีย HP สูงสุด 10% ต่อรอบ",
  str_maze_word_desc_5309004 = "สร้างภาพลวงตาที่จุดเริ่มต้นของการเชื่อมต่อของ Aurorians ภาพลวงตานี้เชื่อมโยงกับ Aurorians ผ่านสายโซ่และโอนส่วนหนึ่งของความเสียหายที่ได้รับและ HP ที่ฟื้นฟูของ Aurorians ไปยังมัน",
  str_maze_word_desc_5309005 = "เมื่อใดก็ตามที่ผู้เล่นกระเด็นถอยหลัง ภาพลวงตาจะถูกสร้างขึ้นข้างๆ ผู้เล่น ภาพลวงตานี้เชื่อมโยงกับ Aurorians ผ่านสายโซ่ที่ช่วยให้พวกเขาสามารถแบ่งปันความเสียหายที่ได้รับและฟื้นฟู HP",
