  str_maze_word_desc_11150832 = "เมื่อ Helios กลายเป็น Test State Helios เขาจะได้รับ ATK เพิ่มขึ้น 5% ต่อทุกๆ 1 Wailer ในสนามรบ",
  str_maze_word_11160411 = "การขยายพันธุ์ไข่แมงมุม",
  str_maze_word_desc_11160411 = "ราชินีแมงมุมจะเรียกไข่แมงมุมบ่อยขึ้น",
