  str_maze_word_desc_11160412 = "Spider Queen จะไม่เรียกแมงมุมเพื่อล่า Aurorians อีกต่อไป แต่จะใช้เหยื่อบ่อยขึ้น",
  str_maze_word_11160413 = "เว็บอันตราย",
  str_maze_word_desc_11160413 = "ใยแมงมุมที่ราชินีแมงมุมและฟักลิงแมงมุมปั่นจะไม่หายไปอีกต่อไปหลังจากผ่านไป 1 รอบ",
  str_maze_word_5312101 = "ดูด HP เมื่อเคลื่อนไหว",
