  str_maze_word_402652 = "คลุ้มคลั่ง",
  str_maze_word_desc_402652 = "เพิ่ม ATK พื้นฐานของ Aurorians 15% ในรอบนี้ หาก Active Skill พร้อมเมื่อเริ่มรอบ",
  str_maze_word_402653 = "กระหายเลือด",
  str_maze_word_desc_402653 = "เพิ่มความเสียหาย Active Skill ของ Aurorians 30% และฟื้นฟู HP 10% ของความเสียหาย Active Skill",
  str_maze_word_40263 = "สาปแช่งสังหาร",
  str_maze_word_40264 = "กำแพงแห่งแสงสว่าง",
  str_maze_word_desc_40263 = "เปลี่ยนความเสียหายที่ทำโดยยูนิตฝ่ายเดียวกันเป็นคำสาป เมื่อค่าคำสาปของเป้าหมายเกิน HP มันจะถูกกำจัดทันที",
  str_maze_word_desc_40264 = "มีกำแพงแห่งแสงอยู่ในฉากที่สามารถขัดขวางความก้าวหน้าของศัตรูได้",
