  str_maze_word_40285 = "พระเครื่องตำหนิ",
  str_maze_word_40286 = "การแปลงองค์ประกอบ",
  str_maze_word_desc_40267 = "ยิ่งยูนิตมีขนาดใหญ่ ก็ยิ่งได้รับดาเมจจากการโจมตีเป้าหมายเดียวมากขึ้น",
  str_maze_word_desc_40268 = "ก้อนกรวดที่อยู่เหนือ Wormgate จะเสีย 1 HP ทุกรอบ Wormgate เปิดขึ้นหลังจากที่ Pebbles หายไป",
  str_maze_word_desc_40269 = "ปืนใหญ่อัตตาจรจะเข้าสู่สถานะ Rabid ทุก ๆ 3 รอบ มอบโล่ให้ตัวเองเท่ากับ HP สูงสุด 10%",
  str_maze_word_desc_40270 = "เมื่อปืนใหญ่อัตตาจรมีเกราะป้องกัน มันจะเรียก Orb of Healing 2 ลูกทุกรอบ",
  str_maze_word_desc_40271 = "หลังจาก Skill Banning Steles และ Orbs of Healing ตาย กับดักอีกอันจะถูกเรียกขึ้นมาบนไทล์ที่พวกเขายึดครอง",
  str_maze_word_desc_40272 = "Mirren Gautier เรียกหนวดหนวดออกมาทุกรอบ\nเมื่อ Aurorian เริ่มเคลื่อนไหว Tentaclaw จะขดตัวและฟื้นฟู HP ให้กับ Mirren Gautier",
  str_maze_word_desc_402721 = "หนวดมี HP น้อยมาก ฆ่า Tentaclaw เพื่อเอาแผ่นกระเบื้องที่เสียหายใต้ Mirren Gautier ออกเพื่อเปิดเผย",
  str_maze_word_desc_40273 = "เมื่อมีร์เรน กอทิเยร์ถูกดึงกลับหรือโดนกระแทก พลังโจมตีเพิ่มขึ้นและพลังป้องกันลดลงในรอบเดียวกัน (ผลของเอฟเฟกต์นี้ไม่สามารถซ้อนทับกัน)",
  str_maze_word_desc_40274 = "เมื่อ Mirren Gautier ถูกซ่อน จะเพิ่ม ATK แต่ลด DEF ลงอย่างมาก",
  str_maze_word_desc_40275 = "ภาพหลอนรับเฉพาะดาเมจเป้าหมายเดียว 50% ของดาเมจที่รับจะถูกส่งต่อไปยัง Dreamwalker",
  str_maze_word_desc_40276 = "เมื่อตาย กระเบื้อง Phantasms ที่เปิดอยู่จะกลายเป็นกระเบื้องแตก The Phantom ฟื้นคืนชีพในรอบต่อไป",
  str_maze_word_desc_40277 = "เมื่อกับดักใด ๆ ถูกทำลาย, พลังโจมตีของ Dreamwalker เพิ่มขึ้นและพลังป้องกันลดลงอย่างมาก (สามารถซ้อนกันได้สูงสุด 2 ครั้ง), และ ACT ของ Dreamwalker และโคลนของมันจะลดลงเหลือ 1",
  str_maze_word_desc_40278 = "ในระลอกแรก, Dreamwalker สตัน ไม่ได้รับความเสียหายใด ๆ และกู้คืนพลังชีวิตสูงสุด 5% ในทุกรอบ ในช่วงเวลานี้ มันจะทำความเสียหายให้กับออโรเรียนที่เคลื่อนที่ภายใน 1 กลุ่มที่อยู่รอบ ๆ มัน\nระลอกที่สองเริ่มต้นเมื่อศัตรูอื่น ๆ ทั้งหมดถูกฆ่า หลังจากนั้น Dreamwalker จะไม่สตันอีกต่อไป",
  str_maze_word_desc_40279 = "ความเสียหายที่ได้รับจากร่างโคลนของ Schummer จะถูกโอนไปยัง Schummer ร่างโคลนจะมึนงง 1 รอบหลังจากที่มันกลายเป็นอมตะ จากนั้นมันจะฟื้น HP ทั้งหมดของมัน",
  str_maze_word_desc_40280 = "เมื่อ Schummer ซิงโครไนซ์ HP หาก Aurorians อยู่ใกล้ Schummer มากขึ้น ร่างโคลนจะเปลี่ยนที่อยู่ตาม Schummer",
  str_maze_word_desc_40281 = "ค่า DEF ของ Schummer เพิ่มขึ้น 30% สำหรับแต่ละ Schummer Clone ที่ทำให้มึนงง และร่างโคลนจะสร้างความเสียหายภายใน 1 กลุ่มรอบ ๆ เมื่อสิ้นสุดรอบ",
  str_maze_word_desc_40282 = "ร่างโคลนของ Schummer จะสลับไปมาระหว่างสถานะปกติและสถานะมึนงง เมื่อ HP ลดลงจนเหลือศูนย์ มันจะเปลี่ยนไปใช้รูปแบบอื่น\nSchummer Clones ปกติสูญเสีย 1/3 HP ทุกรอบ",
  str_maze_word_desc_40283 = "Schummer สร้าง Wormgate ที่เธออยู่เมื่อเธอตาย Wormgate จะถูกทำลายในรอบต่อไป และ Schummer จะคืนชีพด้วย 50% ของ HP สูงสุด",
  str_maze_word_desc_40284 = "ทุกรอบที่ชูมเมอร์รอดชีวิต พลังโจมตีเพิ่ม 5% และพลังป้องกันเพิ่ม 10%",
  str_maze_word_desc_40285 = "โครว์อายมีภูมิคุ้มกันต่อความเสียหายที่ทำโดย Aurorians แต่ความเสียหายที่ทำกับเมิร์กไมต์จะถูกโอนไปยังโครว์อาย",
  str_maze_word_desc_40286 = "ธาตุของโครว์อายเปลี่ยนทุกรอบตามลำดับ น้ำ ไฟ ป่า และฟ้าร้อง ความเสียหายที่ถ่ายโอนไปยัง Croweye จาก Murkmites ซึ่งเป็นธาตุเดียวกันกับ Croweye ในแต่ละรอบเพิ่มขึ้น 50%",
  str_maze_word_40287 = "สไนป์คู่",
  str_maze_word_40288 = "สไนป์คู่",
  str_maze_word_40289 = "เป่าโดยตรง",
  str_maze_word_40290 = "ป้อมปราการ",
  str_maze_word_desc_40287 = "เมื่อ Sniper Aurorian ใช้ Chain Combo มันจะใช้เวลาเพิ่มขึ้น 1 ครั้งที่จุดเริ่มต้น",
  str_maze_word_desc_40288 = "เมื่อ Sniper Aurorian ใช้ Chain Combo มันจะใช้เวลาเพิ่มขึ้น 1 ครั้งที่จุดเริ่มต้น",
  str_maze_word_desc_40289 = "Aurorians สร้างความเสียหายเพิ่มเติม 50% แก่ศัตรูที่พวกเขาทำเครื่องหมายไว้",
