  str_maze_word_40296 = "เงาและไฟ",
  str_maze_word_desc_40291 = "พลังของ Evil Eye ไหลออกมาจากช่องว่าง สร้างเกราะป้องกันรอบตัวมัน จำนวนโล่ที่ได้รับทุกรอบจะเพิ่มขึ้นเมื่อสูญเสีย HP มากขึ้น",
  str_maze_word_desc_40292 = "มินเนี่ยนของ Hylingerr ทุ่มเทแรงกายแรงใจเพื่อสกัดกั้นการโจมตีทั้งหมดที่ได้รับในรอบนี้",
  str_maze_word_desc_40293 = "หินสามารถกีดขวางทาง ใช้ทุบคน และหยิบขึ้นมาเพื่อป้องกันความเสียหาย การทำลาย Pebbles จะให้โล่เท่ากับ 5% ของ HP สูงสุด",
  str_maze_word_desc_40294 = "Shire และ Shelt แข็งแกร่งยิ่งขึ้น ได้รับ DEF มากมาย",
  str_maze_word_desc_40295 = "เมื่อ Shadowgeists และ Gloom Ghouls ที่ถูกเรียกขึ้นโดย Shire และ Shelt ตายลง สองพี่น้องรู้สึกถึงอันตรายที่พวกเขากำลังเผชิญหน้า และเริ่มโจมตีโดยไม่คำนึงถึงพลังป้องกัน (DEF) ของตัวเอง",
  str_maze_word_desc_40296 = "ความเร็วในการโจมตีของ Gloom Ghoul เพิ่มขึ้น! ตอนนี้พวกเขาโจมตีสองครั้งทุกรอบ",
