  str_maze_word_8001024 = "ไปตามกระแส",
  str_maze_word_8001025 = "ซ่อมแซมฉุกเฉิน",
  str_maze_word_desc_8001001 = "Gloomghast ได้รับคำย่อของขั้นสูง: การเสริมสร้าง II",
  str_maze_word_desc_8001002 = "อิคลิพไซท์จะโจมตีปกติสองครั้งเมื่อกำลังโจมตี",
  str_maze_word_desc_8001003 = "อิคลิพไซท์ขนาดใหญ่ได้รับคำเติมขั้นสูง: ปราณยามะ III",
  str_maze_word_desc_8001004 = "อิคลิพไซท์จับตุ๊กตาและเมื่อพ่ายแพ้ จะส่งต่อให้อิคลิพไซท์คนอื่นโดยสุ่ม ระวังอิคลิพไซท์ที่จับตุ๊กตานะ!",
  str_maze_word_desc_8001005 = "เมื่อ Forest Evil Eyes ปรากฏขึ้น พวกเขาจะหลับใหลในรอบ 3 รอบ ในระหว่างนั้น Water Evil Eyes จะประสบการณ์ลดพลังป้องกันอย่างมาก",
  str_maze_word_desc_8001006 = "ณ สิ้นรอบ หากอิคลิพไซท์ถือเคานท์โล่ มันจะทำดาเมจคงที่เท่ากับ 5% ของพลังชีวิตสูงสุดของทีมออโรเรียนให้ทั้งทีม",
  str_maze_word_desc_8001007 = "อิคลิพไซท์ได้รับแรงบันดาลใจและเพิ่มพลังโจมตีของตัวเองอย่างมากอย่างชัดเจน",
  str_maze_word_desc_8001008 = "การโจมตีของออโรเรียนทั้งหมดได้รับผลของดูดพลังชีวิตอย่างมาก",
  str_maze_word_desc_8001009 = "ความเสียหายจากคอมโบต่อเนื่องของออโรเรียนเพิ่มขึ้น 25% ในขณะที่ความเสียหายจากโจมตีปกติลดลง 15%",
  str_maze_word_desc_8001010 = "Gloomghast ได้รับคำยกย่องขั้นสูง: พรอันวิเศษ II",
  str_maze_word_desc_8001011 = "ถ้า Prober ไม่ถูกโจมตีในรอบนี้, พลังป้องกันของ Croweye จะเพิ่มขึ้นในรอบถัดไป",
  str_maze_word_desc_8001012 = "โครว์อาย ได้รับคำย่อขั้นสูง: ซุ่มยิงจุดระเบิด",
  str_maze_word_desc_8001013 = "ประสิทธิภาพของ Shadow สูงขึ้นอย่างมาก ทำให้สามารถข้ามรูน Phase และเรียก Shadowgeists โดยตรง",
  str_maze_word_desc_8001014 = "ในขณะเชื่อมต่อชิ้นกระเบื้อง พลังโจมตีของออโรเรียนทั้งหมดเพิ่มขึ้น 20%",
  str_maze_word_desc_8001015 = "ในขณะที่เชื่อมต่อชิ้นส่วน การโจมตีที่มากขึ้นต่ออิคลิพไซท์ จะทำให้พลังโจมตีของคอมโบเชื่อมโยงของออโรเรียนสูงขึ้น",
  str_maze_word_desc_8001016 = "เงื่อนไขชนะพิเศษ: พ่ายแพ้ Enferno",
  str_maze_word_desc_8001017 = "Spellhounds จะยังคงเกิดขึ้นใหม่จนกว่า Enferno จะถูกพ่ายแพ้",
  str_maze_word_desc_8001018 = "ก่อนที่ผู้เล่นจะเชื่อมต่อชิ้นส่วน, สำหรับแต่ละครั้งที่ทำดาเมจ, ทีมทั้งหมดจะได้รับการเพิ่มพลังโจมตี 1% หลังจากเชื่อมต่อชิ้นส่วน",
  str_maze_word_desc_8001019 = "อัปเกรดทักษะของผู้เรียกมืด",
  str_maze_word_desc_8001020 = "อิคลิพไซท์ทั้งหมดบนสนามพลังเรียกคืนพลังชีวิต 5% ในทุกรอบ",
  str_maze_word_desc_8001021 = "เมื่ออิคลิพไซท์ตาย อิคลิพไซท์ทั้งหมดในสนามพลังจะได้รับการเพิ่มพลังโจมตี",
