  str_maze_word_desc_40315 = "หากศัตรูถูกโจมตีและรอดชีวิตเป็นเวลา 2 รอบ ศัตรูจะกลายเป็นอมตะและเชื่อมโยงกับ Aurorian ในขณะที่เชื่อมโยง ศัตรูจะสูญเสีย HP ในแต่ละรอบเพื่อสร้างความเสียหายให้กับ Aurorian และลด DEF ของ Aurorian ในรอบที่เหลือของการรอดชีวิต",
