  str_maze_word_desc_40318 = "ตราธาตุสายฟ้าของแชโดว์วอล์กเกอร์เพิ่มขึ้นอย่างทีละค่อย สำหรับแต่ละรอบ หากจำนวนการโจมตีปกติของทีมต่อแชโดว์วอล์กเกอร์น้อยกว่าตัวตราธาตุสายฟ้า แชโดว์วอล์กเกอร์จะเรียกใช้การโจมตีธาตุสายฟ้าต่อออโรเรียน",
