  str_maze_word_desc_40322 = "เมื่อใดก็ตามที่ Aurorian ถูกโจมตี จะมีจุดโคลน 3 จุดเกิดขึ้นภายใน 1 กลุ่มที่อยู่รอบ ๆ",
