  str_maze_word_70011052 = "การเดินแรก",
  str_maze_word_desc_70011052 = "ในรอบที่สี่ คูลดาวน์ของสกิลทั้งหมดของ Aurorian จะลดลง 1 รอบ แต่จักรพรรดิแห่งความตายมีสกิล End of Fate ที่น่าหวาดเสียวอย่างยิ่ง",
  str_maze_word_70011061 = "ความพยายามร่วมกัน",
  str_maze_word_desc_70011061 = "โทรุปรากฏขึ้นในสนามรบเพื่อให้กำลังใจแก่เพื่อน ๆ โดยการใช้สกิลทุกรอบและทำดาเมจ 5 ครั้ง\nความสามารถนี้ยังจะรีเซ็ตช่องที่ไม่ใช่สีเหลืองภายใน 1 วงรอบใกล้เคียง",
  str_maze_word_70011062 = "การเดินแรก",
  str_maze_word_desc_70011062 = "ในรอบที่สี่ คูลดาวน์ของสกิลของ Aurorian ทั้งหมดจะลดลง 1 รอบ แต่ Schummer มีความสามารถในการเพิ่มคุณสมบัติของตัวเองอย่างมาก",
