  str_maze_word_5361004 = "พันธะ",
  str_maze_word_desc_5361001 = "มอนสเตอร์ได้รับความเสียหายร้ายแรงเมื่อถูกกระแทกกลับไปยังขอบของสนาม",
  str_maze_word_desc_5361002 = "มอนสเตอร์ได้รับความเสียหายและมึนงงเมื่อถูกกระแทกกลับไปยังขอบของสนาม",
