  str_maze_word_40367 = "ขอบการขัดขวาง II",
  str_maze_word_40368 = "การเสริมสร้างภาพลวงตา",
  str_maze_word_40369 = "แฟนท่อมกัดกร่อน",
  str_maze_word_desc_40355 = "Aurorians และมอนสเตอร์ได้รับความเสียหายเมื่อถูกกระเด็นกลับไปยังขอบของสนาม",
  str_maze_word_desc_40356 = "คุณจะแพ้การต่อสู้เมื่อฟาฟนีร์ตาย กรุณาปกป้องเขา!",
  str_maze_word_desc_40357 = "ศัตรูจะได้รับโบนัส ATK และ DEF เมื่อฟาฟนีร์ตาย โปรดทำเสียที่สุดในการป้องกันเขา!",
  str_maze_word_desc_40358 = "ความเสียหายสุดท้ายที่ศัตรูได้รับจะเพิ่มขึ้นตามประเภทร่างกายของพวกเขาเมื่อได้รับความเสียหายจากการโจมตีเป้าหมายเดียว",
  str_maze_word_desc_40359 = "ออโรเรียนและศัตรูได้รับความเสียหายและลด DEF เมื่อถูกกระแทกกลับไปยังขอบของสนาม มีผลใช้งาน 1 รอบ",
  str_maze_word_desc_40360 = "เพิ่มพลังโจมตีปกติของออโรเรียน",
  str_maze_word_desc_40361 = "Aurorians ฟื้นฟู HP ขึ้นอยู่กับความเสียหายจาก Chain Combo ของพวกเขา",
  str_maze_word_desc_40362 = "เมื่อกลางคืนและกลางวันสลับช่วงเวลากัน รอยฟกช้ำของศัตรูจะแปลงเป็น HP และ DEF ของพวกเขาจะเพิ่มขึ้น",
  str_maze_word_desc_40363 = "เมื่อกลางคืนและกลางวันสลับช่วงเวลากัน ATK ของทั้งฝ่ายเดียวกันและศัตรูจะเพิ่มขึ้น",
  str_maze_word_desc_40364 = "ทุกๆ 3 รอบ จะมี Crimson Specter ปรากฏขึ้นในสนามรบ",
  str_maze_word_desc_40365 = "พันธมิตรและศัตรูได้รับความเสียหายแท้เมื่อย้ายไปหรือถูกย้ายไปยัง Lethal Spears",
  str_maze_word_desc_40366 = "ศัตรูเอลิทจะเริ่มชาร์จพลังเมื่อคืนเริ่มต้น ย้ายตำแหน่งพวกเขาเพื่อขัดขวางความคืบหน้า ศัตรูจะได้รับ ACT เพิ่มเติมและโบนัสความเสียหายมากขึ้นในรอบนี้หลังจากที่พวกเขาชาร์จเสร็จ",
  str_maze_word_desc_40367 = "โฟโรชั่นเรียกทัมเปอร์เมื่อสร้างภาพลวงตา พันธมิตรและศัตรูได้รับความเสียหายและลดพลังป้องกันเมื่อถูกกระทืบย้อนกลับไปข้างขอบสนาม มีผลใช้งาน 1 รอบ",
  str_maze_word_desc_40368 = "เรียกภาพมายา 1 ตัวลงสนามรบทุกรอบ โจมตีและป้องกันของภาพมายาจะเพิ่มขึ้นตามรอบจนถึงขีดจำกัด",
  str_maze_word_desc_40369 = "เพิ่ม ATK ของ Aurorians แต่ลด DEF ของพวกเขาเมื่อ Illusion ถูกควบคุม ผลกระทบนี้สามารถซ้อนกันได้",
  str_maze_word_5014001 = "ดาวตกไฟแรง",
  str_maze_word_desc_5014001 = "เรียกอุกกาบาตมาโจมตีเป้าหมายที่มี HP สูงสุดทุกครั้งที่ผ่านไป 4 แผ่นกระเบื้องสีแดง",
  str_maze_word_5014002 = "น้ำรักษา",
  str_maze_word_desc_5014002 = "ออโรเรียนฟื้นฟู HP ทุก 4 ช่องสีน้ำเงินที่เดินผ่าน",
  str_maze_word_40370 = "แสงสว่างโบราณ",
  str_maze_word_40371 = "แสงสว่างโบราณ",
  str_maze_word_40372 = "เสียงสะท้อนแห่งพลัง",
