  str_maze_word_40374 = "ยาแก้พิษมีชีวิต",
  str_maze_word_40375 = "ยาแก้พิษมีชีวิต",
  str_maze_word_desc_40370 = "พื้นที่ที่ไม่เคยถูกสัมผัสมานับเป็นพันปีปกปิดแสงที่แข็งแกร่งที่สุด\nการใช้ Active Skills สร้าง 2 กระเบื้องมืดรอบ ๆ บอสสูงสุด 3 ครั้งในแต่ละรอบ",
  str_maze_word_desc_40371 = "พื้นที่ที่ไม่เคยถูกสัมผัสมานับเป็นเอียนซ์ปกปิดแสงที่แข็งแกร่งที่สุด\nการใช้ Active Skills สร้าง 1 กระเบื้องมืดรอบ ๆ บอสสูงสุด 3 ครั้งในแต่ละรอบ",
  str_maze_word_desc_40372 = "หลังจากผ่านช่องมืด สามารถเพิ่ม ATK ของออโรเรียนทั้งหมดในทีม โดยแต่ละสแต็กเพิ่ม ATK 1% สามารถสะสมสแต็กได้",
  str_maze_word_desc_40373 = "ใบของ Diavola จะแข็งขึ้นหลังจากพัฒนา ลดความเสียหายที่ได้รับใน 8 ช่องนอกสุด",
