  str_maze_word_desc_5370001 = "แปลงกระเบื้อง 3 แผ่นเป็นกระเบื้องสีเข้มทุกรอบ",
  str_maze_word_desc_5370002 = "แปลง 4 กระเบื้องเป็นกระเบื้องสีเข้มในแต่ละรอบ",
  str_maze_word_desc_5370003 = "แปลง 5 กระเบื้องเป็นกระเบื้องสีเข้มในแต่ละรอบ",
  str_maze_word_desc_5370011 = "แปลง 1 ช่องภายใน 1 คลัสเตอร์รอบ ๆ ของ Aurorians เป็น Dark Tile ในแต่ละรอบ",
  str_maze_word_desc_5370012 = "เปลี่ยน 2 ช่อง ภายใน 1 คลัสเตอร์รอบ ๆ ของออโรเรียนเป็น Dark Tiles ในแต่ละรอบ",
  str_maze_word_desc_5370013 = "เปลี่ยน 4 ช่อง ในวงรอบตัว 2 ชั้นของออโรเรียนเป็นกระเบื้องมืดในแต่ละรอบ",
  str_maze_word_desc_5371001 = "เพิ่มความเสียหายจากคอมโบต่อเนื่องของออโรเรียน 30%",
  str_maze_word_desc_5371002 = "เพิ่มความเสียหายของสกิลใช้งานของออโรเรียน 30%",
  str_maze_word_desc_5371003 = "ความเสียหายพิษที่ Rebecca Venomswamp ทำให้ศัตรูไม่สนใจค่า DEF",
  str_maze_word_desc_5371004 = "ผลของพิษที่มีต่อ Aurorians จะถูกกำจัดเมื่อพวกเขาผ่านไปข้าง Isa ภายใน 1 กลุ่มรอบ ๆ",
  str_maze_word_desc_5372001 = "สร้างความเสียหายให้มอนสเตอร์ 10 ครั้งเพื่อปล้น 10% ของ ATK และ 10% ของ DEF ของมอนสเตอร์",
  str_maze_word_desc_5372002 = "ออโรเรียนได้รับพิษ 1 สแต็กในแต่ละรอบ",
  str_maze_word_desc_5372003 = "ฟื้นฟู HP เมื่อเก็บขึ้น และรักษาผลของพิษทั้งหมด",
  str_maze_word_desc_5372004 = "ในตอนเริ่มต้นของแต่ละรอบ แปลงชิ้นส่วนของธาตุกัปตันภายใน 2 วงรอบของออโรเรียนเป็น<color=#FFB400>ช่องมืด</color>",
  str_maze_word_desc_5372005 = "Aurorians สร้างความเสียหายแท้ต่อสัตว์ประหลาดหลังจากผ่านที่กระเบื้องมืด",
  str_maze_word_desc_5372006 = "การต่อสู้จะสิ้นสุดลงด้วยความพ่ายแพ้ถ้าเรเบคกาตาย ปกป้องเธออย่างสุดกำลัง!",
  str_maze_word_desc_5373001 = "เพิ่มความเสียหายจาก Chain Combo ของออโรเรียนในรอบปัจจุบัน 10% เมื่อผ่านที่ช่องมืด สูงสุด 3 สแต็ก",
  str_maze_word_desc_5373002 = "เพิ่มดาเมจโจมตีปกติของออโรเรียนในรอบปัจจุบัน 10% เมื่อเดินผ่านช่องมืด สูงสุด 3 สแต็ก",
  str_maze_word_desc_5373003 = "เพิ่ม ATK ของออโรเรียน 5% ภายใน 2 รอบหลังจากผ่านช่องมืด สูงสุด 3 สแต็ก",
  str_maze_word_8003013 = "คอมพาวนด์ โซ่",
  str_maze_word_8003014 = "พลังทหาร",
  str_maze_word_8003015 = "กำลังทหาร",
  str_maze_word_8003016 = "ดูดพลังชีวิต",
  str_maze_word_desc_8003013 = "ออโรเรียนทั้งหมดในทีมจะร่ายคอมโบต่อเนื่องทั้งหมดที่เงื่อนไขการเรียกใช้ได้ถูกต้องตามลำดับหนึ่งต่อหนึ่ง",
  str_maze_word_desc_8003014 = "ทุกครั้งที่ปืนซัลโวถูกทำลาย กษัตริย์เงือกจะเสีย 5% ของ HP สูงสุดของเขา",
  str_maze_word_desc_8003015 = "ทุกครั้งที่ปืนซัลโวถูกควบคุม กษัตริย์เงือกจะเสีย 3% ของ HP สูงสุดของเขา",
  str_maze_word_desc_8003016 = "ทุกครั้งที่ปราบปืนซัลโว้ ทีมจะฟื้นฟู 5% ของ Max HP",
  str_maze_word_8003001 = "คู่โซ่ตรวน",
