  str_maze_word_8003012 = "การโจมตีแรงกล้า",
  str_maze_word_desc_8003001 = "คอมโบต่อเนื่องของออโรเรียนสามารถร่ายเพิ่มเติม 1 ครั้ง ผลของสกิลนี้ไม่สามารถสะสมกันได้",
  str_maze_word_desc_8003002 = "เมื่อ HP ของปืน Salvo ตกต่ำกว่า 40% มันจะถูกแปลงเป็นฝ่ายของผู้เล่น",
  str_maze_word_desc_8003003 = "เมื่อมีศัตรูน้อยกว่า 3 ตัว กำแพงต้องห้ามในสนามรบจะหายไป",
  str_maze_word_desc_8003004 = "เมื่อมีศัตรูในสนามรบถูกปราบทุกครั้ง ATK ของ Thumper จะเพิ่มขึ้น 20%",
  str_maze_word_desc_8003005 = "เมื่อเคลียร์คลื่น, กำแพงต้องห้ามในสนามรบจะหายไป",
  str_maze_word_desc_8003006 = "มอนสเตอร์ในสนามรบได้รับ ATK 10% ต่อรอบ",
  str_maze_word_desc_8003007 = "กัปตันสามารถร่ายคอมโบต่อเนื่องทั้งหมดที่เงื่อนไขการเริ่มต้นได้รับการตรวจสอบแล้ว ต่อกันหนึ่งครั้ง",
  str_maze_word_desc_8003008 = "เมื่อปืน Salvo ยิงและโดนผู้เล่น จะทำให้ได้รับตราระเบิด 1 สแต็ก เมื่อตราระเบิดสะสมครบ 3 สแต็ก ตราระเบิดจะระเบิด",
  str_maze_word_desc_8003009 = "ATK พื้นฐานของโรบินจะเท่ากับกัปตัน",
