  str_maze_word_desc_70011142 = "ในตอนเริ่มต้นการต่อสู้และเมื่อใช้ Butterfly Onslaught, เจ้าของร้านจะเรียกกระเบื้อง Poison Mark จำนวนมาก",
  str_maze_word_desc_70011143 = "1 ช่องสีเข้มจะปรากฏรอบ ๆ ออโรเรียนในทุกรอบ",
  str_maze_word_desc_70011151 = "สกิลทำความเสียหายพื้นที่ของออโรเรียนสามารถลบทุ่งโคลนและแปลงเป็นช่องที่เป็นธาตุของกัปตัน",
