  str_maze_word_desc_5395002 = "ในรอบนี้ การโจมตีปกติจะเพิ่มความเสียหายจากคอมโบต่อเนื่องของออโรเรียน",
  str_maze_word_desc_5395003 = "เมื่อใช้ Active Skill, จะสร้าง Dark Tiles 2 ช่องบนช่องว่างที่ใกล้ที่สุดกับ Aurorians",
  str_maze_word_desc_5395004 = "ที่เริ่มต้นของแต่ละรอบ สร้าง Dark Tiles บนสี่แผ่นในรูปกากบาทรอบ ๆ Aurorians",
  str_maze_word_desc_5395005 = "ทุก 15 การโจมตีปกติ จะสร้าง 1 ช่องมืดบนช่องว่างที่ใกล้ที่สุดกับ Aurorians",
