  str_maze_word_desc_5395009 = "หลังจากผ่านช่องมืด สามารถเพิ่ม ATK ของออโรเรียนทั้งหมดในทีม โดยแต่ละสแต็กเพิ่ม ATK 1% สามารถสะสมสแต็กได้",
  str_maze_word_desc_5395010 = "Night King Helios ที่ถูกปรับเปลี่ยนไป ไล่แสงทั้งหมดออกจากตัวของมันและสร้าง Dark Tiles 2 ชิ้นบนช่องว่างภายใน 1 คลัสเตอร์รอบ ๆ ในทุกรอบ",
