  str_maze_word_desc_8004003 = "กัปตันสามารถใช้คอมโบต่อเนื่องเพิ่มเติมได้ 1 ครั้ง ผลลัพธ์นี้ไม่สามารถซ้อนทับกันได้",
  str_maze_word_desc_8004004 = "สกิลใช้งานของออโรเรียนสไนเปอร์จะพร้อมใช้งานทันทีทุกครั้งที่ฆ่าศัตรูไป 3 ตัว",
