  str_maze_word_desc_8004009 = "อีลิทอีวิลอายรับความเสียหายเฉพาะที่ถูกโอนมาจากพลังงานดาบ Vile Sword Energy strands เท่านั้น",
  str_maze_word_desc_80040091 = "เส้นพลังงานดาบ Vile มีค่า DEF ที่สูงมากและต้านทานความเสียหายจากการโจมตีปกติ",
  str_maze_word_desc_8004010 = "ทุกฝาผนังที่ถูกห้ามในสนามจะถูกนำออกเมื่อชาวออโรเรียนเหยียบบนกับดักขับไล่ผี",
  str_maze_word_desc_8004011 = "ตรงกลางของ Aurorians, ระยะของ Forbidden Walls จะยุบลดทุกรอบ ระยะของ Forbidden Walls จะขยายออกอีกครั้งเมื่อ Aurorians เหยียบบน Exorcism Trap.",
  str_maze_word_desc_8004012 = "ศัตรูที่อยู่ในระยะของ Forbidden Walls จะไม่ตาย Forbidden Walls จะยังคงถูกสร้างขึ้นในสนามต่อไป",
  str_maze_word_desc_8004013 = "ทุกฝาผนังที่ถูกห้ามในสนามจะถูกนำออกเมื่อชาวออโรเรียนเหยียบบนกับดักขับไล่ผี",
  str_maze_word_desc_8004014 = "กำแพงที่ถูกห้ามจะดำเนินการสร้างต่อไปในสนาม ศัตรูภายในระยะของกำแพงที่ถูกห้ามจะไม่ตาย",
  str_maze_word_desc_8004015 = "ทุกฝาผนังที่ถูกห้ามในสนามจะถูกนำออกเมื่อชาวออโรเรียนเหยียบบนกับดักขับไล่ผี",
  str_maze_word_desc_8004016 = "ทุกรอบ กำแพงต้องห้ามขนาด 3x3 พร้อมทางเข้าจะถูกสร้างขึ้นรอบ ๆ ออโรเรียน ทิศทางของทางเข้าจะเปลี่ยนทุกรอบ และมันจะเล็กลงเมื่อเวลาผ่านไป",
  str_maze_word_desc_8004017 = "พลังของ Augean จะกระชากขึ้นทุก 3 รอบ และทำความเสียหายที่เพิ่มขึ้นอย่างมากในรอบที่พลังของมันกระชากขึ้น",
  str_maze_word_desc_8004018 = "การเหยียบบนกับดักไล่ผีจะอัญเชิญกำแพงต้องห้ามรอบ ๆ ศัตรู กำแพงต้องห้ามเหล่านี้จะหายไปหลังจาก 1 รอบ",
  str_maze_word_desc_8004019 = "กำแพงต้องห้ามที่ใหญ่ขึ้นแต่มีช่องทางจะปรากฏขึ้นในทุกรอบ การเหยียบบนกับดักขับไล่ผีจะลบกำแพงต้องห้ามทั้งหมดบนสนาม",
