  str_maze_word_5411018 = "คลื่นเขา",
  str_maze_word_desc_5411001 = "ก้อนกรวดและชิ้นส่วนที่เสียหายจะถูกสร้างขึ้นแบบสุ่มในสนามรบในแต่ละรอบ",
  str_maze_word_desc_5411002 = "Chen'ni จะช่วยเหลือ Aurorians ในการต่อสู้บนสนามรบ ซึ่งเธอนั้นมีพลังที่ไม่คาดคิด!",
  str_maze_word_desc_5411003 = "มอนสเตอร์เริ่มต้นในสถานะ Slumber และตื่นขึ้นหลังจากได้รับความเสียหายจากกระเบื้อง ทำให้ได้รับการเพิ่ม ATK และ ACT",
  str_maze_word_desc_5411004 = "ณ สิ้นรอบและเมื่อระเบิดระเบิด, ออโรเรียนที่ไม่อยู่ในโซนที่ปลอดภัยจะได้รับความเสียหายอย่างมาก",
  str_maze_word_desc_5411005 = "สร้าง Dark Tile สีแดงข้างๆ ทาบาอัด สำหรับทุก 2 ศัตรูที่ถูกฆ่า",
  str_maze_word_desc_5411006 = "ทุกครั้งที่ย้ายผ่าน Dark Tile จะเพิ่มความเสียหายจาก Active Skill ของ Aurorians ทั้งหมดอย่างถาวร",
  str_maze_word_desc_5411007 = "หลายช่องสีแดงมืดจะถูกสร้างขึ้นรอบๆ พระราชาเงือกในแต่ละรอบ",
  str_maze_word_desc_5411008 = "Nozard เรียก Gloom Ghouls จำนวนมาก จะมี Blue Dark Tiles สร้างขึ้นใต้ทุก Gloom Ghoul ที่ถูกฆ่า",
  str_maze_word_desc_5411009 = "โนซาร์ดเพิ่ม DEF ของตัวเองขึ้นอยู่กับจำนวนของ Gloom Ghouls ที่อยู่ในสนามรบ ยิ่ง Gloom Ghouls มากเท่าไหร่ ค่า DEF ของโนซาร์ดก็ยิ่งสูงขึ้นเท่านั้น",
  str_maze_word_desc_5411010 = "แปลงกระเบื้องสีน้ำเงินสุ่ม 3 แผ่นในสนามรบเป็นกระเบื้องสีเข้มในแต่ละรอบ",
  str_maze_word_desc_5411011 = "เมื่อ Schummer ที่อยู่ตรงกลางกระดาน Alchemy ถูกกำจัด สถานะที่มี DEF สูงและ ATK ต่ำของ Schummer อื่น ๆ จะถูกลบออก",
  str_maze_word_desc_5411012 = "ช่องสีเหลืองที่มืดจะถูกสร้างขึ้นรอบ ๆ ชูมเมอร์ในแต่ละรอบ",
  str_maze_word_desc_5411013 = "ศัตรูมี DEF ที่สูงเป็นอย่างมาก",
  str_maze_word_desc_5411014 = "เกิร์ตเซิร์ดเรียกบริวารหลายตัวเข้าสู่สนามรบในทุกรอบ จะมี Dark Tiles สีเหลืองที่จะถูกสร้างขึ้นใต้ทุกบริวารที่ถูกฆ่า",
  str_maze_word_desc_5411015 = "ออโรเรียนได้รับการเพิ่มพลัง ATK เล็กน้อยเมื่อผ่านทางช่องมืด; เอฟเฟกต์นี้สามารถสะสมได้",
  str_maze_word_desc_5411016 = "หลังจากที่ Aurorian เข้าสู่ Aurora Time จะมีการสร้าง Dark Tiles สีเหลืองหลายแผ่นรอบ ๆ Aurorian",
  str_maze_word_desc_5411017 = "เมื่อ Fiendling: Rats โจมตี Aurorians, พวกมันจะทิ้งระเบิดไว้ที่จุดนั้น ซึ่งจะระเบิดหลังจากหนึ่งรอบและทำให้เกิดความเสียหายต่อเป้าหมายทั้งหมด",
  str_maze_word_desc_5411018 = "คลื่นกระแทก Aurorians ถอยหลังไป 3 ช่องทุกรอบ",
