  str_maze_word_desc_70011232 = "การใช้ Active Skill จะทำให้ Nian ตกใจ ขับไล่มันกลับไป 1 ช่อง และแปลง 2 ช่องด้านหน้าเป็นธาตุของกัปตัน",
  str_maze_word_5411019 = "พันธะแห่งพลังชีวิต",
  str_maze_word_desc_5411019 = "สถานะที่ไม่สามารถสัมผัสได้ของทาบาอัดจะถูกลบออกเมื่อเข้าสู่คลื่นที่ 3",
  str_maze_word_70011251 = "การแปลงร่างแสง",
  str_maze_word_desc_70011251 = "หลังจากการเทเลพอร์ตทุกครั้ง ทีมจะแปลงกระเบื้องที่อ่อนแอภายใน 12 แผ่นในรูปทรงเพชรเป็นกระเบื้องที่ปรับปรุงแล้ว",
  str_maze_word_70011261 = "สำรองลูมินา",
  str_maze_word_desc_70011261 = "รับ 1 ครั้งหลังจากใช้สกิลใช้งานเพื่อทำความเสียหาย, โทรพอร์ต, หรือเปลี่ยนสีช่อง การใช้แต่ละครั้งจะได้รับ 1 ครั้งเท่านั้น",
  str_maze_word_70011262 = "ลูมินาระเบิด",
  str_maze_word_desc_70011262 = "Buff บน Aurorian จะรีเซ็ตหลังจากนับได้ 3 ครั้ง มันจะลดรอบคูลดาวน์ของ Active Skill ของ Aurorian ที่สอดคล้องกัน 1 รอบ และทำความเสียหายให้กับเจ้าของร้าน",
