  str_maze_word_desc_8005002 = "เพิ่มดาเมจจากการโจมตีปกติของกัปตันอย่างมาก",
  str_maze_word_8005003 = "การส่งเสริมความกล้าหาญ",
  str_maze_word_desc_8005003 = "สำหรับทุก Active Skill ที่ Aurorian ใช้ ความเสียหายที่ทำในรอบนี้จะเพิ่มขึ้นอย่างมาก สูงสุด 3 ชั้น",
  str_maze_word_8005004 = "การเสริมพลังทั้งหมด",
