  str_maze_word_desc_8005007 = "พลังงานของหินพิเศษบนสนามจะได้รับจาก Couriers เท่านั้น หินทั้งหมดจะหายไปเมื่อ Couriers ถูกกำจัดออกไปแล้ว",
