  str_maze_word_8015031 = "กร่อนหิน",
  str_maze_word_desc_8015011 = "ฟื้นฟูจำนวนหนึ่งของแต้มพลังในการเริ่มต้นแต่ละรอบ การฟื้นฟูจะเพิ่มขึ้นในแต่ละรอบ (สูงสุด 13 แต้ม)",
  str_maze_word_desc_8015022 = "ในตอนเริ่มของแต่ละรอบ จะสร้างกระเบื้องมืด 2 ชิ้นรอบๆ Aurorians และเมื่อลบกระเบื้องมืดบนสนาม จะฟื้นฟู 1 แต้มพลังสำหรับ Aurorians",
