  str_maze_word_desc_5435001 = "สร้าง Dark Tiles 2 ชิ้นภายใน 2 คลัสเตอร์ที่อยู่รอบ ๆ ของ Aurorians ในแต่ละรอบ",
  str_maze_word_desc_5435002 = "สร้างกระเบื้องมืด 2 แผ่นรอบเจ้าของร้านในแต่ละรอบ",
