  str_maze_word_desc_1002061 = "ทุกๆ 3 รอบ สร้าง Shadowfires ที่กระเบื้องที่อยู่ข้างนอกสุดบนกระดานภายในระยะสูงสุดในพื้นที่ที่มีรูปกากบาทที่อยู่ตรงกลางของ Aurorian และทำความเสียหายเล็กน้อย",
  str_maze_word_desc_1002081 = "ไอราสัมผัสออโรเรียนจากไกล และทุกๆสองรอบ จะโจมตีสนามรบด้วยดาวตก ทำลายศูนย์กลางและสร้างช่องแตก 4 ช่อง",
